UPDATE DAILY_BATCH_EXECUTION
SET lease_until = DATE_ADD(NOW(), INTERVAL #{leaseDurationSeconds} SECOND)
WHERE daily_batch_execution_id = #{id}
  AND owner_id = #{ownerId}
  AND lease_token = #{leaseToken}
  AND status = 'RUNNING'
  AND lease_until >= NOW()

UPDATE DAILY_BATCH_EXECUTION
SET status        = #{status},
    completed_at  = NOW(),
    error_summary = #{errorSummary}
WHERE daily_batch_execution_id = #{id}
  AND owner_id = #{ownerId}
  AND lease_token = #{leaseToken}
  AND status = 'RUNNING'
  AND lease_until >= NOW()
